import{_ as o,o as e,c as s,a3 as r}from"./chunks/framework.BFeCKmyl.js";const p=JSON.parse('{"title":"Histórico de e-mails avançado","description":"","frontmatter":{"title":"Histórico de e-mails avançado","id":"eproc-historico-emails","plataforma":"eproc","grupo":"E-mail","plano":"free","desde":"1.0.2","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-historico-emails"}]]},"headers":[],"relativePath":"funcionalidades/eproc-historico-emails.md","filePath":"funcionalidades/eproc-historico-emails.md"}'),i={name:"funcionalidades/eproc-historico-emails.md"};function t(c,a,d,n,l,m){return e(),s("div",null,a[0]||(a[0]=[r('<h1 id="historico-de-e-mails-avancado" tabindex="-1">Histórico de e-mails avançado <a class="header-anchor" href="#historico-de-e-mails-avancado" aria-label="Permalink to &quot;Histórico de e-mails avançado&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Transforma o campo &quot;Para:&quot; do envio de e-mail do eproc num campo de etiquetas, como no Gmail: cada destinatário vira uma etiqueta removível. O eploc lembra os endereços já usados, sugere destinatários enquanto você digita e limpa os e-mails colados.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, tela de envio de e-mail do processo e campos de e-mail do cadastro de minuta. O gerenciador de contatos fica nas configurações do eploc, no card do recurso (&quot;Gerenciar contatos salvos&quot;), e também pode ser aberto pelo popup.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Abra a tela de envio de e-mail. O campo &quot;Para:&quot; já recebe o foco.</li><li>Digite parte de um nome ou endereço. O eploc sugere contatos já usados, mesmo com abreviações, sem acentos ou com pequenos erros de digitação. Escolha com o mouse ou com as setas do teclado: o item escolhido pelas setas fica destacado, com uma barra azul à esquerda.</li><li>Ao clicar no campo, aparecem também os destinatários que costumam ir junto com os já escolhidos.</li><li>Para colar vários endereços de uma vez, cole um bloco de texto no campo: os e-mails válidos viram etiquetas e o resto é descartado. Endereços no formato <code>Nome &lt;email@exemplo.com&gt;</code> guardam também o nome. Um endereço já usado antes, colado ou digitado sem nome, ganha o nome salvo.</li><li>Se o nome colado for diferente do salvo, a etiqueta fica com o nome colado e mostra um ícone de aviso. Clique nela com o botão direito e escolha <strong>Usar o nome salvo</strong> ou <strong>Salvar no histórico</strong>, que passa a guardar o nome novo.</li><li>Para remover um destinatário, clique no &quot;x&quot; da etiqueta.</li><li>Se a mensagem mencionar anexo(s) e nenhum documento estiver marcado na tabela de anexos, o eploc pergunta se você quer enviar mesmo assim.</li></ol><p>No gerenciador de contatos (configurações do eploc), você pode buscar, editar e excluir contatos e confirmar várias edições de uma vez com <strong>Salvar todos</strong>.</p><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Opção</th><th>Padrão</th><th>Efeito</th></tr></thead><tbody><tr><td>Colorir os chips pelo endereço (cada destinatário com uma cor própria)</td><td>ligada</td><td>Cada destinatário ganha uma cor, sempre a mesma, nas etiquetas do campo &quot;Para:&quot; e nas sugestões de destinatários frequentes. Desligada, as etiquetas ficam cinza.</td></tr></tbody></table><p>Os contatos são gerenciados em <strong>Gerenciar contatos salvos</strong>.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>O campo original do eproc continua existindo, oculto, e é ele que o eproc envia. O eploc o mantém sempre preenchido com os endereços separados por &quot;;&quot;.</li><li>Os contatos ficam neste computador e entram no backup. Também podem ser exportados à parte para compartilhar com colegas (veja <a href="./../geral/backup-arquivo">Backup em arquivo</a>).</li></ul><figure class="demo"><div class="demo__tela"><iframe src="/manual/demos/historico-emails/reel.html" title="Demonstração animada" loading="lazy" tabindex="-1"></iframe></div><figcaption>Demonstração animada</figcaption></figure>',14)]))}const h=o(i,[["render",t]]);export{p as __pageData,h as default};
